// src/components/Topbar.js

import "../styles/Topbar.css";   // ← import the CSS file

function Topbar() {
  return (
    <div className="topbar">         {/* className not class! */}

      <span>
        Call for Customer support:{" "}
        <span className="phone">020 38989565</span>
      </span>

      <div>
        <a href="#">My Account</a>
        <a href="#">Wishlist</a>
        <a href="#">To Checkout</a>
      </div>

    </div>
  );
}

export default Topbar;
